# -*- coding: utf-8 -*-
"""
Keyword dispatch - /KEYWORD blocks -> Model.

``KEYWORD_PARSERS`` maps a deck keyword to its reader, ``MATERIAL_DISPATCH``
maps a /MAT spelling to the law-specific reader, and ``parse_starter_deck``
walks the blocks and calls the reader each keyword resolved to.

Fortran origin: the reading loop ``starter/source/starter/lectur.F``, which
hands every block to its ``hm_read_<keyword>.F`` routine.

Fortran origin: the ``hm_read_*.F`` routines under
``starter/source/**/reader/``, one routine per keyword, all driven from
``starter/source/starter/lectur.F``. Each reader's docstring names the
Fortran routine it mirrors; ``keywords/dispatch.py`` holds the keyword
-> parser table, and ``input/starter_keywords.py`` is a deprecated shim
over this package.
"""

